<script>
(()=>{document.querySelectorAll('[data-stock-open]').forEach(button=>button.addEventListener('click',()=>document.getElementById(button.dataset.stockOpen).showModal()));document.querySelectorAll('[data-stock-close]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));document.querySelectorAll('[data-remove-unit]').forEach(form=>form.addEventListener('submit',event=>{if(!confirm(window.ccsText('Remove this available serial and reduce stock quantity by one?')))event.preventDefault();}));})();
</script>
<script>(()=>{document.querySelectorAll('.editor-window form').forEach(form=>{form.insertAdjacentHTML('beforeend','<input type="hidden" name="stock_dialog" value="'+form.closest('dialog').id+'">');});const recovery={{ Illuminate\Support\Js::from(old('stock_dialog','')) }};if(recovery&&document.getElementById(recovery))document.getElementById(recovery).showModal();if(!recovery&&{{ Illuminate\Support\Js::from((bool)old('sku')) }})document.getElementById('newStock').showModal();const checkbox=document.getElementById('stockHasSerial');function sync(){document.getElementById('stockSerials').hidden=!checkbox.checked;document.getElementById('stockSerials').querySelectorAll('input,textarea,button').forEach(input=>input.disabled=!checkbox.checked);document.getElementById('stockQty').hidden=checkbox.checked;document.getElementById('stockQty').querySelector('input').disabled=checkbox.checked;}const moduleBox=document.querySelector('#newStock [name=is_battery_module]');moduleBox.addEventListener('change',()=>{if(moduleBox.checked)checkbox.checked=true;sync();});checkbox.addEventListener('change',()=>{if(moduleBox.checked)checkbox.checked=true;sync();});if(moduleBox.checked)checkbox.checked=true;sync();})();</script>
